import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = "abc"
    let b = "ab" + "c"
    if a == b {
        io.println("eq")
    } else {
        io.println("ne")
    }
    if a != "abd" {
        io.println("differs")
    } else {
        io.println("same")
    }
    if a != b {
        io.println("prefix-ne")
    } else {
        io.println("same-value")
    }
    return Ok(())
}
